head.script:
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.gLdMktTp = js_market;

// var fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        if (js_market === "1" || js_market === "2") {
            rdo_SPOT_ISU_TRD_MKT_TP_CD.setValue(js_market);
        }
        scwin.setCode();
        await scwin.listSync();
        await scwin.getLstRcvDdtm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35003.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
        await scwin.getLstRcvDdtm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35003.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel_onclick = async function() {
    try {
        if (dts_List.getRowCount() > 0) {
            // 엑셀 로그
            $c.stf.doLogSave("ULDSTF35003.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewOffice(grd_List, "ATS자체거래정지수신", "", 8, 0);
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35003.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35003.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35003.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_LstRcv_OnLoadCompleted
 * @description dts_LstRcv 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_LstRcv_OnLoadCompleted = function(rowcount) {
    try {
        scwin.setLstRcvDdtm(dts_LstRcv.getCellData(1, "RCV_DDTM"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35003.dts_LstRcv_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_LstRcv_OnLoadError
 * @description dts_LstRcv 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_LstRcv_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_LstRcv);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35003.dts_LstRcv_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar4(edt_SDate, 1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35003.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar4(edt_EDate, 2);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35003.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name edt_SDate_OnLastChar
 * @description edt SDate On Last Char 처리
 * @param {*} ch ch
 * @returns {void}
 * @hidden N
 */
scwin.edt_SDate_OnLastChar = function(ch) {
    try {
        afterPopUpCalendar(1); // if(시작일>종료일) 종료일=시작일;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35003.edt_SDate_OnLastChar" });
    }
};

/**
 * @method
 * @name edt_EDate_OnLastChar
 * @description edt EDate On Last Char 처리
 * @param {*} ch ch
 * @returns {void}
 * @hidden N
 */
scwin.edt_EDate_OnLastChar = function(ch) {
    try {
        afterPopUpCalendar(2); // if(시작일>종료일) 시작일=종료일;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35003.edt_EDate_OnLastChar" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35003.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35003.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF35003.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneralForDynamicName" + "&outputMessageId=ATS_SELF_HALT_ISU_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.dscltrend.selfhaltlist" + "&{P}strtDd=" + edt_SDate.getValue() + // 시작일자
        "&{P}endDd=" + edt_EDate.getValue() + // 종료일자
        "&{P}mktTpCd=" + rdo_SPOT_ISU_TRD_MKT_TP_CD.getValue(); // 시장구분

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getLstRcvDdtm
 * @description get Lst Rcv Ddtm 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getLstRcvDdtm = async function() {
    const sbmOptions = {
        id : "sbm_dts_LstRcv",
        action : "/AtsContactInfo.do",
        ref : "",
        target : "dts_LstRcv=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2') {
        rdo_SPOT_ISU_TRD_MKT_TP_CD.setDisabled(true);
    } else {
        rdo_SPOT_ISU_TRD_MKT_TP_CD.setValue('A');
    }
    const nowDate = $c.ut.fn_get_nowDate(dts_Date);
    //  기간 from~ to  셋팅
    edt_SDate.setValue(nowDate);
    edt_EDate.setValue(nowDate);
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
};

/**
 * @method
 * @name setLstRcvDdtm
 * @description set Lst Rcv Ddtm 처리
 * @param {*} sRcvDdtm sRcvDdtm
 * @returns {void}
 * @hidden N
 */
scwin.setLstRcvDdtm = function(sRcvDdtm) {
    txb_LST_RCV.setValue(sRcvDdtm);
};
